# Writes dop853_coefficients.go from the DOP853 tableau (Hairer's dop853.f,
# as SciPy tabulates it), printing every coefficient with the shortest
# representation that round-trips, so the Go constants are bit-identical.
#   uv run --with scipy --with numpy python testdata/gen/dop853_coefficients.py
#   gofmt -w dop853_coefficients.go
import os
from scipy.integrate._ivp import dop853_coefficients as c
def f(v): 
    r=repr(float(v))
    return r
out=[]
out.append("// Code generated by testdata/gen/dop853_coefficients.py from E. Hairer's\n// dop853.f coefficients (as tabulated in Hairer, Nørsett & Wanner, Solving ODEs\n// I, and in SciPy's dop853_coefficients.py); DO NOT EDIT.\n\npackage integrate\n")
out.append("const (\n\tdop853NStages = %d\n\tdop853NStagesExtended = %d\n\tdop853InterpPower = %d\n)\n" % (c.N_STAGES, c.N_STAGES_EXTENDED, c.INTERPOLATOR_POWER))
def vec(name, v):
    return "var %s = []float64{%s}\n" % (name, ", ".join(f(x) for x in v))
def mat(name, m):
    rows = ["\t{%s}," % ", ".join(f(x) for x in r) for r in m]
    return "var %s = [][]float64{\n%s\n}\n" % (name, "\n".join(rows))
out.append(vec("dop853C", c.C))
out.append(mat("dop853A", c.A))
out.append(vec("dop853B", c.B))
out.append(vec("dop853E3", c.E3))
out.append(vec("dop853E5", c.E5))
out.append(mat("dop853D", c.D))
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "dop853_coefficients.go"), "w").write("\n".join(out))
